/**
 * Cancels one plugin's in-flight purge for the ACTIVE household (owner-only; non-owners get 403) — the release lever for a drain that can never complete (a corrupted storage key makes every chunk fail forever, and the write gate would otherwise refuse uploads indefinitely). Returns the row to the never-requested resting state and clears every purge column; the write gate releases immediately. Nothing is deleted or restored by this call: documents the drain already finished are gone (their bytes went first), the rest are untouched. A 409 means no purge is in flight.
 */
export const deleteApiPluginsByPluginIdPurge = <ThrowOnError extends boolean = false>(options: Options<DeleteApiPluginsByPluginIdPurgeData, ThrowOnError>): RequestResult<DeleteApiPluginsByPluginIdPurgeResponses, DeleteApiPluginsByPluginIdPurgeErrors, ThrowOnError> => (options.client ?? client).delete<DeleteApiPluginsByPluginIdPurgeResponses, DeleteApiPluginsByPluginIdPurgeErrors, ThrowOnError>({ url: '/api/plugins/{pluginId}/purge', ...options });

/**
 * Requests a FULL purge of one plugin's data for the ACTIVE household (owner-only; non-owners get 403). REQUIRES the typed confirmation: body confirm must equal the plugin's name exactly — a checkbox is a misclick away, a typed string is the deliberate act (§3.4). Nothing is deleted by this request: it marks the drain 'pending' and records who confirmed; the nightly cron's chunk driver then deletes bytes-before-rows one chunk per invocation (a 200-document vault takes ~5 nightly ticks on the free plan — 50-subrequest cap, 40-object budget), refusing new uploads while the drain is in flight. Completion writes ONE plugin_purged lifecycle receipt in the core audit table (no household FK — the receipt outlives the household, plan §3.4). Idempotent while a drain is already pending/running.
 */
export const postApiPluginsByPluginIdPurge = <ThrowOnError extends boolean = false>(options: Options<PostApiPluginsByPluginIdPurgeData, ThrowOnError>): RequestResult<PostApiPluginsByPluginIdPurgeResponses, PostApiPluginsByPluginIdPurgeErrors, ThrowOnError> => (options.client ?? client).post<PostApiPluginsByPluginIdPurgeResponses, PostApiPluginsByPluginIdPurgeErrors, ThrowOnError>({
    url: '/api/plugins/{pluginId}/purge',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Downloads one archive of one plugin's data for the ACTIVE household (owner-only; non-owners get 403) — the export-before-purge capability (plugin architecture ticket 6, #440, §3.4). Read-only: it never touches the purge machinery and stays available while a drain is in flight (the write gate pauses uploads, never reads). The archive is a stored (uncompressed) ZIP: the plugin's file bytes at their archive paths, a documents.csv and a files.csv with the full metadata (RFC 4180, UTF-8 + BOM, user-controlled cells guarded against spreadsheet formula execution), and a trailing manifest.json whose counts report what the stream delivered (a 0-byte entry where files.csv reports size_bytes > 0 marks bytes that were unavailable at export time; audit rows are internal receipts and are NOT included). Whole documents only — a document's files never split across archives — and at most 40 files per archive (the free plan's 50-subrequest cap: 5 D1 statements + 40 storage reads), so a larger vault chains sequential downloads via the X-Export-Next-Cursor response header: send that cursor back as ?cursor= until the header is absent. The cursor is bound to the issuing household (a foreign one is a 400). The chain is keyset-paginated, not a frozen snapshot: a document uploaded mid-chain is picked up by a later archive unless it commits in the same second as the cursor with a smaller id (the purge driver's known same-second class) — re-request the export to collect stragglers. Writes one plugin_exported lifecycle receipt per archive (owner as actor). No gating with purge: export early, purge whenever the household chooses.
 */
export const getApiPluginsByPluginIdExport = <ThrowOnError extends boolean = false>(options: Options<GetApiPluginsByPluginIdExportData, ThrowOnError>): RequestResult<GetApiPluginsByPluginIdExportResponses, GetApiPluginsByPluginIdExportErrors, ThrowOnError> => (options.client ?? client).get<GetApiPluginsByPluginIdExportResponses, GetApiPluginsByPluginIdExportErrors, ThrowOnError>({ url: '/api/plugins/{pluginId}/export', ...options });

